import java.util.*;

public class Main {
    public static void main(String[] args) {
        char[] s = new Scanner(System.in).next().toCharArray();
        // Greedy from the most significant digit, keeping a valid completion possible.
        if (s[0] == '?') s[0] = (s[1] == '?' || s[1] <= '3') ? '2' : '1';
        if (s[1] == '?') s[1] = s[0] == '2' ? '3' : '9';
        if (s[3] == '?') s[3] = '5';
        if (s[4] == '?') s[4] = '9';
        System.out.println(new String(s));
    }
}

package main

import "fmt"

func main() {
	var line string
	fmt.Scan(&line)
	s := []byte(line)
	// Greedy from the most significant digit, keeping a valid completion possible.
	if s[0] == '?' {
		if s[1] == '?' || s[1] <= '3' {
			s[0] = '2'
		} else {
			s[0] = '1'
		}
	}
	if s[1] == '?' {
		if s[0] == '2' {
			s[1] = '3'
		} else {
			s[1] = '9'
		}
	}
	if s[3] == '?' {
		s[3] = '5'
	}
	if s[4] == '?' {
		s[4] = '9'
	}
	fmt.Println(string(s))
}
